        }

        if(!
                DecoderSession_construct(
                        &decoder_session,
#if FLAC__HAS_OGG
                        options.is_ogg,
                        options.use_first_serial_number,
                        options.serial_number,
#else
                        /*is_ogg=*/false,
                        /*use_first_serial_number=*/false,
                        /*serial_number=*/0,
#endif
                        options.format,
